use crate::app_commands::{AppState,Employee,MonthlySnapshot};
use payroll_storage::{Collection,Page,Session};
use serde::Serialize;
use std::collections::BTreeMap;
use tauri::State;
#[derive(Clone,Serialize)]pub struct CalculationEmployee{pub employee_id:String,pub name:String,pub department:String,pub kind:String,pub version_count:usize,pub latest:MonthlySnapshot}
#[derive(Serialize)]pub struct EmployeeVersions{pub employee_id:String,pub name:String,pub department:String,pub kind:String,pub versions:Vec<MonthlySnapshot>}
pub fn scoped_versions(session:&Session,period:&str,payout:&str)->Result<Vec<MonthlySnapshot>,String>{for date in [period,payout]{chrono::NaiveDate::parse_from_str(&format!("{date}-01"),"%Y-%m-%d").map_err(|_|"所属期及计划发放月格式错误")?;}let mut result=Vec::new();let mut page=1;loop{let rows=session.page::<MonthlySnapshot>(Collection::Calculations,page,100)?;result.extend(rows.records.into_iter().filter(|value|value.period==period&&value.payout_month==payout));if page as u64*100>=rows.total{break}page+=1;}Ok(result)}
pub fn roster(session:&Session,period:&str,payout:&str,query:&str)->Result<Vec<CalculationEmployee>,String>{
 let mut grouped=BTreeMap::<String,CalculationEmployee>::new();for value in scoped_versions(session,period,payout)?{if let Some(row)=grouped.get_mut(&value.employee_id){row.version_count+=1;}else{let person=session.get::<Employee>(Collection::Employees,&value.employee_id)?;grouped.insert(value.employee_id.clone(),CalculationEmployee{employee_id:value.employee_id.clone(),name:person.as_ref().map(|person|person.name.clone()).unwrap_or_else(||value.employee_id.clone()),department:person.as_ref().map(|person|person.department.clone()).unwrap_or_default(),kind:person.as_ref().map(|person|person.kind.clone()).unwrap_or_default(),version_count:1,latest:value});}}
 let needle=query.trim().to_lowercase();Ok(grouped.into_values().filter(|person|needle.is_empty()||[&person.employee_id,&person.name,&person.department].iter().any(|text|text.to_lowercase().contains(&needle))).collect())
}
#[tauri::command]pub fn calculation_employees_page(state:State<AppState>,period:String,payout_month:String,query:String,page:u32,page_size:u32,focus_employee_id:Option<String>)->Result<Page<CalculationEmployee>,String>{state.with_session(|session|{if page==0||![20,50,100].contains(&page_size){return Err("分页参数无效".into());}let rows=roster(session,&period,&payout_month,&query)?;let total=rows.len() as u64;let requested=focus_employee_id.and_then(|id|rows.iter().position(|row|row.employee_id==id)).map(|index|index as u32/page_size+1).unwrap_or(page);let current=requested.min(((total+u64::from(page_size)-1)/u64::from(page_size)).max(1) as u32);Ok(Page{records:rows.into_iter().skip(((current-1)*page_size) as usize).take(page_size as usize).collect(),total,page:current,page_size})})}
#[tauri::command]pub fn calculation_employee_versions(state:State<AppState>,employee_id:String,period:String,payout_month:String)->Result<EmployeeVersions,String>{state.with_session(|session|{let person=session.get::<Employee>(Collection::Employees,&employee_id)?;let versions=scoped_versions(session,&period,&payout_month)?.into_iter().filter(|value|value.employee_id==employee_id).collect();Ok(EmployeeVersions{name:person.as_ref().map(|value|value.name.clone()).unwrap_or_else(||employee_id.clone()),department:person.as_ref().map(|value|value.department.clone()).unwrap_or_default(),kind:person.as_ref().map(|value|value.kind.clone()).unwrap_or_default(),employee_id,versions})})}

#[cfg(test)]mod tests{
 use super::*;
 fn snapshot(subject:&str,employee:&str,id:&str,period:&str,payout:&str)->MonthlySnapshot{serde_json::from_value(serde_json::json!({"id":id,"subject_id":subject,"employee_id":employee,"period":period,"payout_month":payout,"fixed_salary":"10000","performance":"0","adjustment":"0","result":{"gross":"10000","employee_deductions":"800","withholding":null,"net":null,"employer_cost":"11200"},"input":{"employee_id":employee,"period":period,"payout_month":payout,"standard_days":"22","actual_days":"22","performance":"0","adjustment":"0","employee_deductions":"800","employer_contributions":"1200"}})).unwrap()}
 #[test]fn two_employees_with_four_versions_remain_two_employees(){
  let root=std::env::temp_dir().join(format!("calculation-roster-{}",uuid::Uuid::new_v4()));let store=payroll_storage::Store::new(root.clone()).unwrap();let subject=store.create_subject("去重主体","1234","上海","test-password").unwrap();let other=store.create_subject("另一主体","5678","杭州","test-password").unwrap();let mut session=store.unlock(&subject.id,"test-password").unwrap();
  for id in ["E1","E2","E3"]{let employee=Employee{id:id.into(),name:format!("员工{id}"),department:"研发部".into(),cost_center:String::new(),kind:"正式员工".into(),hire_date:"2026-01-01".into(),leave_date:String::new(),base_salary:"10000".into(),effective_from:"2026-01-01".into()};session.upsert(Collection::Employees,id,&employee).unwrap();}
  for id in ["E1","E2"]{for version in [1,2]{let snapshot=snapshot(&subject.id,id,&format!("{id}-v{version}"),"2026-10","2026-11");session.insert_immutable(Collection::Calculations,&snapshot.id,&snapshot).unwrap();}}
  for (id,period,payout) in [("other-payout","2026-10","2026-12"),("other-period","2026-11","2026-12")]{let snapshot=snapshot(&subject.id,"E1",id,period,payout);session.insert_immutable(Collection::Calculations,id,&snapshot).unwrap();}
  let rows=roster(&session,"2026-10","2026-11","").unwrap();assert_eq!(rows.len(),2);assert!(rows.iter().all(|row|row.version_count==2));assert_eq!(rows[0].latest.id,"E1-v2");assert_eq!(rows[1].latest.id,"E2-v2");assert_eq!(scoped_versions(&session,"2026-10","2026-11").unwrap().len(),4);assert_eq!(roster(&session,"2026-10","2026-11","员工E1").unwrap().len(),1);
  assert!(session.get::<MonthlySnapshot>(Collection::Calculations,"E1-v1").unwrap().is_some());let separate=store.unlock(&other.id,"test-password").unwrap();assert!(roster(&separate,"2026-10","2026-11","").unwrap().is_empty());drop(separate);drop(session);let _=std::fs::remove_dir_all(root);
 }
}
